<template><div class="rg"><div class="rg-toolbar"><div><h3>天然气需求与保供影响网络</h3><p>当前为事件示例数据集，不含客户销量节点；悬浮圆点查看信息，点击查看证据。</p></div><select v-model="scenario" @change="selected=null"><option>全部事件场景</option><option>天气影响</option><option>工业生产</option><option>供应保障</option><option>产业链传导</option><option>政策传导</option><option>异常归因</option><option>运输影响</option></select></div><div class="rg-search"><input v-model="query" placeholder="搜索事件或业务问题，如：寒潮、工业用气、供需缺口" aria-label="搜索图谱节点"><select v-model.number="hops"><option :value="1">1层关联</option><option :value="2">2层关联</option><option :value="3">3层关联</option></select><button @click="query='';scenario='全部事件场景';selected=null;render()">重置视图</button></div><div class="rg-results" v-if="query"><button v-for="node in matches.slice(0,8)" :key="node.name" @click="focus=node.name;selected=node;render()">{{node.name}}</button><span v-if="!matches.length">未找到相关节点，试试“天气影响”等场景或更短的关键词。</span></div><p class="rg-scope">展示范围：{{scenario}}<span v-if="query.trim()"> · “{{query}}”的{{hops}}层关联</span><span v-else> · 未进行搜索</span>｜事件数据集共 {{nodes.length}} 个节点、{{edges.length}} 条关系</p><div class="rg-stats"><span><b>{{visibleNodes.length}}</b> 当前展示节点</span><span><b>{{visibleEdges.length}}</b> 当前展示关系</span><span>事件 → 驱动因素 → 需求变化 → 业务行动</span></div><div class="rg-layout"><div class="rg-canvas" ref="host"><div ref="chartEl" class="rg-chart"></div><div class="rg-navigation"><div><button v-for="control in controls" :key="control.label" :aria-label="control.label" :title="control.label" @click="control.action()"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path :d="control.path"/></svg></button></div></div><div class="rg-legend"><span v-for="(c,i) in categories" :key="c"><i :style="{background:colors[i]}"/>{{c}}</span></div></div><aside><template v-if="selected"><small>节点详情</small><h3>{{selected.name}}</h3><span class="rg-tag">{{categories[selected.category]}}</span><p>{{selected.description}}</p><h4>关联关系</h4><div class="rg-relation" v-for="(edge,i) in related" :key="i"><b>{{edge.source}} → {{edge.target}}</b><p>{{edge.label}}</p><small>依据：{{edge.evidence}}</small></div><button @click="$emit('analyze','请分析'+selected.name+'对天然气业务的影响，说明影响路径与证据。')">在会话中分析</button></template><template v-else><small>关系探索</small><h3>点击节点查看详情</h3><p>选择网络中的事件、驱动因素、需求或行动，查看其直接关联与说明。</p><h4>典型业务路径</h4><p>寒潮降温 → 采暖负荷 → 城燃需求 → 高峰保障</p><p>集中复产 → 生产负荷 → 工业用气 → 采购调整</p><p>管道检修 → 输送受限 → 供需缺口 → 备用气源</p></template></aside></div><p class="rg-foot">支持拖动空白处平移、拖动节点调整位置、双指滑动画布，或使用方向与缩放按钮。所有关系均为业务示例，真实判断需结合天气、销量及服务数据验证。</p></div></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import * as echarts from 'echarts'
import {graphTooltip,wrapGraphText} from './graphPresentation.js'
defineEmits(['analyze']);const query=ref(''),hops=ref(2),focus=ref('');const scenario=ref('全部事件场景'),selected=ref(null),chartEl=ref(),host=ref(),nodes=ref([]),edges=ref([]),categories=['事件','驱动因素','需求与风险','业务行动'],colors=['#2557c5','#007d81','#b36508','#7538af'];let chart,observer
const sceneNodes=computed(()=>nodes.value.filter(n=>scenario.value==='全部事件场景'||n.scenarios.includes(scenario.value)))
const matches=computed(()=>sceneNodes.value.filter(n=>n.name.includes(query.value.trim())||n.description.includes(query.value.trim())))
const visibleNodes=computed(()=>{if(!query.value.trim())return sceneNodes.value;const root=focus.value&&matches.value.some(n=>n.name===focus.value)?focus.value:matches.value[0]?.name;if(!root)return [];const allowed=new Set(sceneNodes.value.map(n=>n.name)),seen=new Set([root]);for(let i=0;i<hops.value;i++){const next=new Set(seen);for(const edge of edges.value){if(seen.has(edge.source)&&allowed.has(edge.target))next.add(edge.target);if(seen.has(edge.target)&&allowed.has(edge.source))next.add(edge.source)}seen.clear();next.forEach(n=>seen.add(n))}return sceneNodes.value.filter(n=>seen.has(n.name)).slice(0,60)})

const visibleEdges=computed(()=>{const ids=new Set(visibleNodes.value.map(n=>n.name));return edges.value.filter(e=>ids.has(e.source)&&ids.has(e.target))})
const related=computed(()=>visibleEdges.value.filter(e=>e.source===selected.value?.name||e.target===selected.value?.name))
const controls=[
{label:'放大',path:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15M16 16l5 5M10.5 7v7M7 10.5h7',action:()=>zoom(1.2)},
{label:'缩小',path:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15M16 16l5 5M7 10.5h7',action:()=>zoom(1/1.2)},
{label:'复位',path:'M3 10a9 9 0 1 1 2 8M3 4v6h6',action:()=>render()}
]

function pan(dx,dy){chart?.dispatchAction({type:'graphRoam',seriesIndex:0,dx,dy})}
function zoom(factor){chart?.dispatchAction({type:'graphRoam',seriesIndex:0,zoom:factor,originX:chart.getWidth()/2,originY:chart.getHeight()/2})}
function wheelPan(event){event.preventDefault();event.stopImmediatePropagation();if(event.ctrlKey||event.metaKey){zoom(Math.exp(-event.deltaY*.008))}else{const unit=event.deltaMode===1?16:event.deltaMode===2?chart.getHeight():1;pan(-event.deltaX*unit,-event.deltaY*unit)}}
function render(){if(!chart)return;const data=visibleNodes.value;chart.setOption({animationDurationUpdate:350,tooltip:graphTooltip(p=>{if(p.dataType==='edge')return `${p.data.source} → ${p.data.target}\n关系：${p.data.label}\n${wrapGraphText(p.data.evidence)}`;const n=p.data;return `${n.name}\n类型：${categories[n.category]}\n场景：${n.scenarios.join('、')}\n直接关联：${edges.value.filter(e=>e.source===n.name||e.target===n.name).length} 条\n${wrapGraphText(n.description)}`}),series:[{type:'graph',layout:'force',force:{initLayout:'circular',repulsion:850,edgeLength:[150,210],gravity:.07,layoutAnimation:false},roam:true,draggable:true,symbol:'circle',symbolSize:48,symbolKeepAspect:true,scaleLimit:{min:.4,max:3},data:data.map(n=>({...n,id:n.name,symbol:'circle',symbolSize:48,itemStyle:{color:colors[n.category],borderColor:'#fff',borderWidth:3,shadowBlur:7,shadowColor:'#18345322'},label:{show:false,position:'bottom',distance:9,color:'#192e49',fontSize:12,fontWeight:600,width:130,overflow:'break',backgroundColor:'#ffffffee',padding:[3,5],borderRadius:3}})),links:visibleEdges.value.map(e=>({...e,value:e.label})),edgeSymbol:['none','arrow'],edgeSymbolSize:[0,10],lineStyle:{color:'#687d9a',opacity:.85,width:2,curveness:.08},edgeLabel:{show:false},labelLayout:{hideOverlap:true},emphasis:{focus:'adjacency',scale:1.15,label:{show:false},lineStyle:{color:'#234f91',width:3,opacity:1}},blur:{itemStyle:{opacity:.35},lineStyle:{opacity:.12},label:{opacity:.35}}}]},true)}

onMounted(async()=>{try{const r=await fetch('/reasoning-graph.json');if(!r.ok)throw Error();const data=await r.json();nodes.value=data.nodes;edges.value=data.edges;chart=echarts.init(chartEl.value);chartEl.value.addEventListener('wheel',wheelPan,{capture:true,passive:false});render();chart.on('click',p=>{if(p.dataType==='node')selected.value=nodes.value.find(n=>n.name===p.name)});observer=new ResizeObserver(()=>chart.resize());observer.observe(host.value)}catch{if(host.value)host.value.textContent='图谱数据加载失败，请刷新重试。'}})
watch(scenario,()=>{focus.value='';render()});watch([query,hops],()=>{focus.value='';selected.value=null;render()});onBeforeUnmount(()=>{chartEl.value?.removeEventListener('wheel',wheelPan,true);observer?.disconnect();chart?.dispose()})
</script>
<style scoped>
.rg-toolbar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:25px 0 18px}.rg-toolbar h3{font-size:17px;color:#46566e}.rg-toolbar p{font-size:11px;color:#9ba6b6;margin-top:8px}.rg-toolbar select{background:white;border:1px solid #dfe5ef;border-radius:7px;padding:9px 15px;color:#7989a1;font-size:12px}.rg-stats{display:flex;align-items:center;gap:25px;font-size:11px;color:#9aa7ba;margin-bottom:20px}.rg-stats b{font-size:19px;color:#6682b5;margin-right:5px}.rg-stats span:last-child{margin-left:auto}.rg-layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;border:1px solid #e3e9f2;border-radius:12px;overflow:hidden;min-height:550px}.rg-canvas{position:relative;background:radial-gradient(#dce4f1 .8px,transparent .8px);background-size:20px 20px;min-width:0}.rg-chart{width:100%;height:570px}.rg-legend{position:absolute;bottom:16px;left:18px;display:flex;gap:16px;background:#ffffffdd;padding:9px 12px;border-radius:8px}.rg-legend span{display:flex;align-items:center;gap:5px;font-size:10px;color:#8696ad}.rg-legend i{width:8px;height:8px;border-radius:50%}.rg-layout aside{padding:22px;background:#fafbfd;border-left:1px solid #e5eaf2}.rg-layout aside>small{font-size:10px;color:#a4afbf}.rg-layout aside h3{font-size:17px;margin:12px 0;color:#556781}.rg-layout aside p{font-size:12px;color:#93a1b4;line-height:1.9;margin:12px 0}.rg-layout aside h4{font-size:12px;color:#7b8da7;margin-top:25px}.rg-tag{font-size:10px;background:#edf2fc;padding:4px 8px;border-radius:4px;color:#7892bd}.rg-relation{padding:12px 0;border-bottom:1px solid #e5eaf2}.rg-relation b{font-size:11px;color:#7e91af}.rg-relation p{margin:5px 0!important;font-size:11px!important}.rg-relation small{font-size:10px;color:#a9b2c0;line-height:1.7}.rg-layout button{border:1px solid #d7e1f2;color:#6e8aba;padding:9px 13px;border-radius:6px;font-size:11px;margin-top:20px}.rg-foot{font-size:10px;color:#a5afbe;margin-top:15px}@media(max-width:1000px){.rg-layout{grid-template-columns:1fr}.rg-layout aside{border-left:0;border-top:1px solid #e5eaf2}.rg-stats span:last-child{display:none}}

.rg-search{display:flex;gap:10px;margin:20px 0 12px}.rg-search input{flex:1;min-width:0;border:1px solid #dce5f2;border-radius:9px;padding:12px 15px;font:inherit;font-size:12px;color:#65758c;background:#fafcfe}.rg-search select,.rg-search button{border:1px solid #e0e6f0;background:white;border-radius:8px;padding:8px 12px;font-size:11px;color:#7a8ba3}.rg-results{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:15px}.rg-results button{border:1px solid #dce6f7;background:#f3f7ff;border-radius:16px;padding:5px 12px;font-size:11px;color:#6d87b5}.rg-results>span{font-size:12px;color:#9aa7bb}.rg-canvas{background-color:#fcfdff;background-image:radial-gradient(#e4eaf4 .7px,transparent .7px);background-size:24px 24px}.rg-chart{height:560px}.rg-layout{box-shadow:0 3px 18px #455b7d05}.rg-layout aside{background:#fff}.rg-legend{border:1px solid #edf0f6}.rg-stats{margin-top:18px}
.rg-toolbar h3{color:#24344d}.rg-toolbar p,.rg-stats,.rg-foot{color:#74839a}.rg-layout aside p{color:#65758c}.rg-layout aside h3{color:#263b58}.rg-canvas{background:#fafcff}.rg-legend span{color:#4f617b}.rg-chart{height:600px}
.rg-stats{font-size:12px;color:#455872}.rg-stats b{color:#254f91}.rg-canvas{background:#f6f9fe}.rg-layout aside small,.rg-relation small{color:#60748f}.rg-legend{pointer-events:none}.rg-legend span{color:#324a69}.rg-search input,.rg-toolbar select,.rg-search select,.rg-search button{color:#3e5473}
.rg-scope{font-size:12px;color:#526985;background:#eef3fb;border:1px solid #dde6f3;border-radius:7px;padding:10px 12px;margin:14px 0}

.rg-chart{touch-action:none;cursor:grab;overscroll-behavior:contain}.rg-chart:active{cursor:grabbing}.rg-navigation{position:absolute;right:14px;top:14px;z-index:2;display:flex;flex-direction:column;align-items:flex-end;gap:8px;pointer-events:none}.rg-navigation>span{font-size:10px;color:#697d99;background:#fffffff0;padding:6px 9px;border-radius:5px}.rg-navigation>div{display:flex;gap:3px;padding:4px;border:1px solid #dce4f0;background:white;border-radius:7px;box-shadow:0 3px 10px #293f6310;pointer-events:auto}.rg-navigation button{margin:0!important;padding:5px 9px!important;border:0!important;border-radius:4px!important;font-size:12px!important;color:#415f86!important}.rg-navigation button:hover{background:#edf3fc}
.rg-navigation button{display:grid;place-items:center;width:30px;height:30px;padding:0!important}.rg-navigation>div{gap:2px;padding:3px}
</style>
